export function renderSprite(def, white) {
  const px = 10;
  const rows = def.map.length, cols = def.map[0].length;
  const c = document.createElement("canvas");
  c.width = cols * px;
  c.height = rows * px;
  const g = c.getContext("2d");
  for (let y = 0; y < rows; y++) {
    const row = def.map[y].padEnd(cols, ".");
    for (let x = 0; x < cols; x++) {
      const ch = row[x];
      if (ch === "." || !def.palette[ch]) continue;
      g.fillStyle = white ? "#ffffff" : def.palette[ch];
      g.fillRect(x * px, y * px, px, px);
    }
  }
  return c;
}

export function makeSprite(def) {
  const d = {
    map: def.map,
    palette: def.palette,
    eyeL: def.eyeL,
    eyeR: def.eyeR,
    eyeR_: def.eyeR_,
    mouth: def.mouth,
    cheek: def.cheek,
    eyeColor: def.eyeColor || "#26221f",
    singleEye: !!def.singleEye
  };
  d.cols = def.map[0].length;
  d.rows = def.map.length;
  d.colors = Object.keys(def.palette).map((k) => def.palette[k]);
  d.img = renderSprite(d, false);
  d.imgWhite = renderSprite(d, true);
  d.thumb = d.img.toDataURL();
  return d;
}

const ICON_URL_CACHE = {};
export function iconUrl(kind, id) {
  const key = kind + ":" + id;
  if (!ICON_URL_CACHE[key]) {
    const def = kind === "skill"
      ? SKILL_ICONS[id]
      : kind === "ability"
      ? ABILITY_ICONS[id]
      : ACH_ICONS[id] || ACH_ICON_FALLBACK;
    if (!def) return "";
    ICON_URL_CACHE[key] = renderSprite({ palette: def.palette, map: def.map }, false).toDataURL();
  }
  return ICON_URL_CACHE[key];
}

// Hand and skins sprite cache
let HAND_SPRITE = null;
let HAND_ASLEEP = null;
let SKIN_ART = null;

export function getHandSprite() {
  if (HAND_SPRITE) return { main: HAND_SPRITE, asleep: HAND_ASLEEP };
  const img = new Image();
  img.src = HAND_URI;
  const c = document.createElement("canvas");
  img.onload = () => {
    c.width = img.naturalWidth || 92;
    c.height = img.naturalHeight || 92;
    const ctx = c.getContext("2d");
    ctx.drawImage(img, 0, 0);
    HAND_SPRITE = c;
    
    // Asleep hand (tinted / rotated)
    const g = document.createElement("canvas");
    g.width = c.width;
    g.height = c.height;
    const gx = g.getContext("2d");
    gx.drawImage(c, 0, 0);
    HAND_ASLEEP = g;
  };
  return { main: c, asleep: c };
}
